int orangesRotting(int**a,int n,int*c){if(!n)return 0;int m=c[0],*q=malloc(n*m*sizeof(int)),head=0,tail=0,fresh=0,time=0;for(int i=0;i<n;i++)for(int j=0;j<m;j++){if(a[i][j]==2)q[tail++]=i*m+j;if(a[i][j]==1)fresh++;}int d[5]={0,1,0,-1,0};while(head<tail&&fresh){int stop=tail;while(head<stop){int x=q[head++],i=x/m,j=x%m;for(int k=0;k<4;k++){int u=i+d[k],v=j+d[k+1];if(u>=0&&u<n&&v>=0&&v<m&&a[u][v]==1){a[u][v]=2;fresh--;q[tail++]=u*m+v;}}}time++;}free(q);return fresh?-1:time;}
